{"path":"neuron_growth_ollama-mimo-v2.6-flash-rl-mxfp4_01.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Neuron Growth</title>
<style>
  /* ---- page shell: dark background, centered canvas ---- */
  html, body {
    margin: 0; padding: 0; height: 100%;
    background: #05070f;
    overflow: hidden;
    font-family: "Courier New", monospace;
  }
  #stage {
    position: fixed; inset: 0;
    display: flex; align-items: center; justify-content: center;
  }
  canvas {
    width: 800px; height: 800px;
    display: block;
    box-shadow: 0 0 60px rgba(0, 229, 255, 0.12), 0 0 140px rgba(16, 26, 58, 0.9);
    border: 1px solid rgba(0, 229, 255, 0.18);
  }
  /* subtle dat.gui styling tweak */
  .dg.main .title { letter-spacing: 1px; text-transform: uppercase; }
</style>
</head>
<body>
<div id="stage">
  <canvas id="c" width="800" height="800"></canvas>
</div>

<!-- dat.gui: the only external library -->
<script src="https://cdn.jsdelivr.net/npm/dat-gui@0.7.9/build/dat.gui.min.js"></script>
<script>
(function () {
  'use strict';

  // ============================================================
  // SETUP - constants, canvas, palette
  // ============================================================
  const W = 800, H = 800;
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');

  // offscreen layer for the static grid (redrawn only when needed)
  const gridCanvas = document.createElement('canvas');
  gridCanvas.width = W; gridCanvas.height = H;
  const gctx = gridCanvas.getContext('2d');

  const params = {
    // Growth
    neuronCount: 5,
    growthSpeed: 2.2,
    maxDepth: 5,
    splitChance: 0.16,
    curvature: 0.35,
    maxLength: 130,
    // Synapses
    synapseThreshold: 46,
    synapseGlow: 0.75,
    // Pulses
    pulseSpeed: 160,
    pulseFrequency: 0.55,
    pulseBrightness: 1.0,
    // Visuals
    backgroundColor: '#05070f',
    glowColor: '#101a3a',
    branchColor: '#00e5ff',
    accentColor: '#d6ff00',
    synapseColor: '#ff2bd6',
    pulseColor: '#fff36a',
    uiColor: '#ffd400',
    showGrid: true,
    showScanlines: true,
    vignetteStrength: 0.75
  };

  let paused = false;
  let time = 0;

  // ============================================================
  // GUI SETUP - folders and controls
  // ============================================================
  function buildGUI() {
    const gui = new dat.GUI({ width: 300 });

    const fGrowth = gui.addFolder('Growth');
    fGrowth.add(params, 'neuronCount', 3, 6, 1).name('neuron count').onFinishChange(regenerate);
    fGrowth.add(params, 'growthSpeed', 0.2, 6, 0.1).name('branch growth speed');
    fGrowth.add(params, 'maxDepth', 1, 8, 1).name('max branch depth').onFinishChange(regenerate);
    fGrowth.add(params, 'splitChance', 0, 0.6, 0.01).name('branch split chance');
    fGrowth.add(params, 'curvature', 0, 1, 0.01).name('branch curvature');
    fGrowth.add(params, 'maxLength', 40, 260, 1).name('max branch length');
    fGrowth.open();

    const fSyn = gui.addFolder('Synapses');
    fSyn.add(params, 'synapseThreshold', 10, 120, 1).name('synapse distance threshold');
    fSyn.add(params, 'synapseGlow', 0, 2, 0.05).name('synapse glow strength');
    fSyn.open();

    const fPulse = gui.addFolder('Pulses');
    fPulse.add(params, 'pulseSpeed', 20, 500, 1).name('pulse speed');
    fPulse.add(params, 'pulseFrequency', 0, 3, 0.05).name('pulse frequency');
    fPulse.add(params, 'pulseBrightness', 0, 2, 0.05).name('pulse brightness');
    fPulse.open();

    const fVis = gui.addFolder('Visuals');
    fVis.addColor(params, 'backgroundColor').name('background color').onChange(buildGrid);
    fVis.addColor(params, 'glowColor').name('background glow');
    fVis.addColor(params, 'branchColor').name('branch color');
    fVis.addColor(params, 'accentColor').name('accent branch color');
    fVis.addColor(params, 'synapseColor').name('synapse color');
    fVis.addColor(params, 'pulseColor').name('pulse color');
    fVis.add(params, 'showGrid').name('dark grid').onChange(buildGrid);
    fVis.add(params, 'showScanlines').name('scanlines');
    fVis.add(params, 'vignetteStrength', 0, 1, 0.05).name('vignette');
    fVis.open();

    const actions = {
      regenerate: function () { regenerate(); },
      clearCanvas: function () { clearCanvas(); },
      togglePause: function () { paused = !paused; }
    };
    gui.add(actions, 'regenerate').name('regenerate network');
    gui.add(actions, 'clearCanvas').name('clear canvas');
    gui.add(actions, 'togglePause').name('pause / resume animation');

    return gui;
  }

  // ============================================================
  // NEURON GROWTH - seed neurons and recursive branches
  // ============================================================
  let branches = [];   // all grown branch objects
  let tips = [];       // active growing tips
  let synapses = [];   // links between nearby tips
  let pulses = [];     // travelling sparks
  let branchCount = 0;
  const MAX_BRANCHES = 900;
  let growthDone = false;

  function rand(a, b) { return a + Math.random() * (b - a); }

  function makeBranch(x, y, angle, depth, width) {
    if (branchCount >= MAX_BRANCHES) return null;
    branchCount++;
    const b = {
      x0: x, y0: y,
      cx: x, cy: y,          // quadratic control point
      x: x, y: y,            // current tip
      angle: angle,
      depth: depth,
      width: width,
      len: 0,
      targetLen: rand(params.maxLength * 0.4, params.maxLength),
      curve: rand(-params.curvature, params.curvature),
      accent: Math.random() < 0.22,
      phase: rand(0, Math.PI * 2),
      points: [[x, y]],
      done: false
    };
    branches.push(b);
    tips.push(b);
    return b;
  }

  // create seed neurons near the canvas centre
  function regenerate() {
    branches = []; tips = []; synapses = []; pulses = [];
    branchCount = 0; growthDone = false;
    const n = Math.round(params.neuronCount);
    const cx = W / 2, cy = H / 2;
    for (let i = 0; i < n; i++) {
      const ox = cx + rand(-90, 90);
      const oy = cy + rand(-90, 90);
      const arms = Math.floor(rand(3, 6));
      for (let a = 0; a < arms; a++) {
        const ang = (a / arms) * Math.PI * 2 + rand(-0.4, 0.4);
        makeBranch(ox, oy, ang, 0, rand(2.2, 3.4));
      }
    }
    clearCanvas();
  }

  // advance every active tip one small step
  function growStep(dt) {
    if (growthDone) return;
    const steps = Math.max(1, Math.round(params.growthSpeed * 4));
    const dtStep = dt / steps;

    for (let s = 0; s < steps; s++) {
      for (let i = tips.length - 1; i >= 0; i--) {
        const b = tips[i];
        // organic wandering direction
        b.angle += b.curve * dtStep * 6 + rand(-0.35, 0.35) * params.curvature * dtStep * 8;
        const stepLen = 5 * params.growthSpeed * dtStep;
        const nx = b.x + Math.cos(b.angle) * stepLen;
        const ny = b.y + Math.sin(b.angle) * stepLen;
        b.len += stepLen;
        b.x = nx; b.y = ny;

        // keep the branch inside the canvas
        if (nx < 10 || nx > W - 10) { b.angle = Math.PI - b.angle; b.x = Math.max(12, Math.min(W - 12, nx)); }
        if (ny < 10 || ny > H - 10) { b.angle = -b.angle; b.y = Math.max(12, Math.min(H - 12, ny)); }

        // record points sparsely for smooth quadratic rendering
        if (b.points.length < 40) b.points.push([b.x, b.y]);
        b.cx += (b.x - b.cx) * 0.15;
        b.cy += (b.y - b.cy) * 0.15;

        // occasional small side branch
        if (Math.random() < params.splitChance * dtStep * 2 && b.depth < params.maxDepth && branchCount < MAX_BRANCHES) {
          const side = Math.random() < 0.5 ? 1 : -1;
          makeBranch(b.x, b.y, b.angle + side * rand(0.5, 1.1), b.depth + 1, b.width * rand(0.5, 0.8));
        }

        // finish this branch when long enough or too deep / too many
        if (b.len >= b.targetLen || b.depth >= params.maxDepth || branchCount >= MAX_BRANCHES) {
          b.done = true;
          tips.splice(i, 1);
        }
      }
    }

    if (tips.length === 0 || branchCount >= MAX_BRANCHES) growthDone = true;
  }

  // ============================================================
  // SYNAPSE DETECTION - connect nearby tips, no duplicates
  // ============================================================
  function detectSynapses() {
    const thr = params.synapseThreshold;
    for (let i = 0; i < tips.length; i++) {
      for (let j = i + 1; j < tips.length; j++) {
        const a = tips[i], b = tips[j];
        if (a === b) continue;
        const dx = a.x - b.x, dy = a.y - b.y;
        const d2 = dx * dx + dy * dy;
        if (d2 > thr * thr) continue;
        // skip if these two branches are already linked
        let dup = false;
        for (let k = 0; k < synapses.length; k++) {
          const s = synapses[k];
          if ((s.a === a && s.b === b) || (s.a === b && s.b === a)) { dup = true; break; }
        }
        if (dup) continue;
        synapses.push({ a: a, b: b, phase: rand(0, Math.PI * 2), born: time });
        // occasionally fire a pulse right away
        if (Math.random() < 0.4) spawnPulse(a, b);
      }
    }
  }

  // ============================================================
  // PULSE ANIMATION - sparks travelling across synapses
  // ============================================================
  function spawnPulse(a, b) {
    if (pulses.length > 60) return;
    pulses.push({
      a: a, b: b,
      t: 0,
      dur: Math.max(0.25, dist(a, b) / Math.max(20, params.pulseSpeed)),
      w: rand(1.6, 3.0)
    });
  }

  function dist(a, b) { const dx = a.x - b.x, dy = a.y - b.y; return Math.sqrt(dx * dx + dy * dy); }

  function updatePulses(dt) {
    // spawn new pulses at the configured frequency
    if (!growthDone && Math.random() < 0) { /* no spawns during growth */ }
    if (synapses.length && Math.random() < params.pulseFrequency * dt) {
      const s = synapses[Math.floor(Math.random() * synapses.length)];
      spawnPulse(s.a, s.b);
    }
    for (let i = pulses.length - 1; i >= 0; i--) {
      const p = pulses[i];
      p.t += dt / p.dur;
      if (p.t >= 1) {
        // hand the spark over to a neighbouring synapse to keep paths alive
        const next = pickNeighbour(p.b, p.a);
        if (next && Math.random() < 0.6) {
          pulses[i] = { a: p.b, b: next, t: 0, dur: Math.max(0.25, dist(p.b, next) / Math.max(20, params.pulseSpeed)), w: p.w };
        } else {
          pulses.splice(i, 1);
        }
      }
    }
  }

  function pickNeighbour(node, avoid) {
    const cands = [];
    for (let i = 0; i < synapses.length; i++) {
      const s = synapses[i];
      if (s.a === node && s.b !== avoid) cands.push(s.b);
      else if (s.b === node && s.a !== avoid) cands.push(s.a);
    }
    if (!cands.length) return null;
    return cands[Math.floor(Math.random() * cands.length)];
  }

  // ============================================================
  // RENDERING - branches, synapses, pulses, effects
  // ============================================================
  function buildGrid() {
    gctx.clearRect(0, 0, W, H);
    if (!params.showGrid) return;
    gctx.strokeStyle = 'rgba(0, 229, 255, 0.08)';
    gctx.lineWidth = 1;
    for (let x = 0; x <= W; x += 40) { gctx.beginPath(); gctx.moveTo(x + 0.5, 0); gctx.lineTo(x + 0.5, H); gctx.stroke(); }
    for (let y = 0; y <= H; y += 40) { gctx.beginPath(); gctx.moveTo(0, y + 0.5); gctx.lineTo(W, y + 0.5); gctx.stroke(); }
  }

  function clearCanvas() {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.shadowBlur = 0;
    ctx.fillStyle = params.backgroundColor;
    ctx.fillRect(0, 0, W, H);
  }

  function drawBackground() {
    // solid base
    ctx.globalAlpha = 1;
    ctx.shadowBlur = 0;
    ctx.fillStyle = params.backgroundColor;
    ctx.fillRect(0, 0, W, H);

    // soft central glow using the background glow colour
    const g = ctx.createRadialGradient(W / 2, H / 2, 40, W / 2, H / 2, W * 0.7);
    g.addColorStop(0, hexToRgba(params.glowColor, 0.85));
    g.addColorStop(1, hexToRgba(params.glowColor, 0));
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);

    // faint animated noise bands (canvas only, very cheap)
    ctx.globalAlpha = 0.05;
    ctx.fillStyle = params.glowColor;
    const off = (time * 12) % 60;
    for (let y = -60; y < H; y += 60) {
      ctx.fillRect(0, y + off, W, 1);
    }
    ctx.globalAlpha = 1;

    if (params.showGrid) ctx.drawImage(gridCanvas, 0, 0);
  }

  function drawBranches() {
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    for (let i = 0; i < branches.length; i++) {
      const b = branches[i];
      if (b.points.length < 2) continue;
      const col = b.accent ? params.accentColor : params.branchColor;
      ctx.strokeStyle = col;
      ctx.lineWidth = b.width;
      ctx.shadowColor = col;
      ctx.shadowBlur = 10 + Math.sin(time * 2 + b.phase) * 3;

      ctx.beginPath();
      ctx.moveTo(b.points[0][0], b.points[0][1]);
      for (let p = 1; p < b.points.length - 1; p++) {
        const mx = (b.points[p][0] + b.points[p + 1][0]) / 2;
        const my = (b.points[p][1] + b.points[p + 1][1]) / 2;
        ctx.quadraticCurveTo(b.points[p][0], b.points[p][1], mx, my);
      }
      const last = b.points[b.points.length - 1];
      ctx.lineTo(last[0], last[1]);
      ctx.stroke();

      // brighter tip while still growing
      if (!b.done) {
        ctx.beginPath();
        ctx.fillStyle = '#ffffff';
        ctx.shadowColor = col;
        ctx.shadowBlur = 16;
        ctx.arc(b.x, b.y, b.width * 0.7, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.shadowBlur = 0;
  }

  function drawSynapses() {
    const glow = params.synapseGlow;
    for (let i = 0; i < synapses.length; i++) {
      const s = synapses[i];
      const pulseAmt = 0.55 + 0.45 * Math.sin(time * 3 + s.phase);
      const alpha = Math.min(1, 0.35 * glow + 0.5 * pulseAmt * glow);
      ctx.strokeStyle = hexToRgba(params.synapseColor, Math.min(1, alpha));
      ctx.lineWidth = 1.4;
      ctx.shadowColor = params.synapseColor;
      ctx.shadowBlur = 8 + 18 * glow * pulseAmt;
      ctx.beginPath();
      ctx.moveTo(s.a.x, s.a.y);
      ctx.lineTo(s.b.x, s.b.y);
      ctx.stroke();

      // bright node at each end
      ctx.beginPath();
      ctx.fillStyle = hexToRgba(params.synapseColor, Math.min(1, 0.5 + 0.5 * pulseAmt));
      ctx.arc(s.a.x, s.a.y, 2.4, 0, Math.PI * 2);
      ctx.arc(s.b.x, s.b.y, 2.4, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.shadowBlur = 0;
  }

  function drawPulses() {
    const bright = params.pulseBrightness;
    for (let i = 0; i < pulses.length; i++) {
      const p = pulses[i];
      const t = p.t;
      const x = p.a.x + (p.b.x - p.a.x) * t;
      const y = p.a.y + (p.b.y - p.a.y) * t;
      // fading trail
      const tx = p.a.x + (p.b.x - p.a.x) * Math.max(0, t - 0.12);
      const ty = p.a.y + (p.b.y - p.a.y) * Math.max(0, t - 0.12);
      ctx.strokeStyle = hexToRgba(params.pulseColor, 0.5 * bright);
      ctx.lineWidth = p.w * 0.8;
      ctx.shadowColor = params.pulseColor;
      ctx.shadowBlur = 18 * bright;
      ctx.beginPath();
      ctx.moveTo(tx, ty);
      ctx.lineTo(x, y);
      ctx.stroke();
      // spark head
      ctx.beginPath();
      ctx.fillStyle = hexToRgba('#ffffff', Math.min(1, bright));
      ctx.arc(x, y, p.w, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.fillStyle = hexToRgba(params.pulseColor, Math.min(1, bright));
      ctx.arc(x, y, p.w * 2.1, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.shadowBlur = 0;
  }

  function drawEffects() {
    // scanlines
    if (params.showScanlines) {
      ctx.globalAlpha = 0.10;
      ctx.fillStyle = '#000000';
      for (let y = 0; y < H; y += 4) ctx.fillRect(0, y, W, 2);
      ctx.globalAlpha = 1;
    }
    // vignette
    const v = params.vignetteStrength;
    if (v > 0) {
      const g = ctx.createRadialGradient(W / 2, H / 2, W * 0.28, W / 2, H / 2, W * 0.72);
      g.addColorStop(0, 'rgba(0,0,0,0)');
      g.addColorStop(1, 'rgba(0,0,0,' + (0.85 * v) + ')');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }
  }

  // small colour helper: hex -> rgba string
  function hexToRgba(hex, a) {
    let h = hex.replace('#', '');
    if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
    const r = parseInt(h.substring(0, 2), 16);
    const g = parseInt(h.substring(2, 4), 16);
    const b = parseInt(h.substring(4, 6), 16);
    if (isNaN(r) || isNaN(g) || isNaN(b)) return 'rgba(255,255,255,' + a + ')';
    return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
  }

  // ============================================================
  // MAIN LOOP
  // ============================================================
  let last = performance.now();
  function loop(now) {
    let dt = (now - last) / 1000;
    last = now;
    if (dt > 0.1) dt = 0.1;   // clamp after tab switches

    if (!paused) {
      time += dt;
      growStep(dt);
      detectSynapses();
      updatePulses(dt);
    }

    drawBackground();
    drawBranches();
    drawSynapses();
    drawPulses();
    drawEffects();

    requestAnimationFrame(loop);
  }

  // ============================================================
  // BOOT
  // ============================================================
  buildGrid();
  buildGUI();
  regenerate();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
"}
